package com.example.meetomxh.supabase;
import org.json.JSONObject;
public final class SupabaseAuthClient {
 public static Subscription login(String email,String password,Api.Callback<JSONObject> cb){if(SessionManager.getInstance().getCurrentUser()!=null)SessionManager.getInstance().clear();return Api.run(()->{JSONObject s=(JSONObject)SupabaseHttpClient.raw("POST","/auth/v1/token?grant_type=password",Api.obj("email",email.trim(),"password",password),null);SessionManager.getInstance().accept(s);return RpcClient.object("bootstrap_profile",Api.obj());},cb);}
 private static String challenge(boolean recovery)throws Exception{byte[] random=new byte[32];new java.security.SecureRandom().nextBytes(random);String verifier=android.util.Base64.encodeToString(random,android.util.Base64.URL_SAFE|android.util.Base64.NO_PADDING|android.util.Base64.NO_WRAP);SessionManager.getInstance().pending("pkce",verifier);SessionManager.getInstance().pending("recovery",recovery?"yes":"no");return android.util.Base64.encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(java.nio.charset.StandardCharsets.US_ASCII)),android.util.Base64.URL_SAFE|android.util.Base64.NO_PADDING|android.util.Base64.NO_WRAP);}
 public static void signup(String email,String password,Api.Callback<JSONObject> cb){Api.run(()->(JSONObject)SupabaseHttpClient.raw("POST","/auth/v1/signup?redirect_to=meeto%3A%2F%2Fauth%2Fcallback",Api.obj("email",email.trim(),"password",password,"code_challenge",challenge(false),"code_challenge_method","s256"),null),cb);}
 public static void recover(String email,Api.Callback<JSONObject> cb){Api.run(()->(JSONObject)SupabaseHttpClient.raw("POST","/auth/v1/recover?redirect_to=meeto%3A%2F%2Fauth%2Fcallback",Api.obj("email",email.trim(),"code_challenge",challenge(true),"code_challenge_method","s256"),null),cb);}
 public static JSONObject exchange(String code)throws Exception {String verifier=SessionManager.getInstance().pending("pkce");if(verifier.isEmpty())throw new java.io.IOException("Missing verifier");JSONObject result=(JSONObject)SupabaseHttpClient.raw("POST","/auth/v1/token?grant_type=pkce",Api.obj("auth_code",code,"code_verifier",verifier),null);SessionManager.getInstance().accept(result);SessionManager.getInstance().pending("pkce","");RpcClient.object("bootstrap_profile",Api.obj());return result;}
 public static JSONObject verify(String hash,String type) throws Exception {JSONObject result=(JSONObject)SupabaseHttpClient.raw("POST","/auth/v1/verify",Api.obj("token_hash",hash,"type",type),null);if(result.has("access_token"))SessionManager.getInstance().accept(result);return result;}
 public static void password(String newPassword,Api.Callback<JSONObject> cb){Api.run(()->(JSONObject)SupabaseHttpClient.authorized("PUT","/auth/v1/user",Api.obj("password",newPassword)),cb);}
}
